"""Emit the canonical-value ruling table to AutoGenerated/canonical_values.json.

Single source of truth for every quantity the 2026-08 peer review found
published with multiple incompatible values. Downstream consumers (prose
templating, drift auditors, the website) read this file instead of
restating numbers. See simulations/core/canonical_values.py for the
rulings and their weighing rationale.

Also cross-checks each canonical value against the live registry
(parameters.json) where a registry path exists, so a regression that
re-introduces a superseded value is visible in the build log.
"""
from __future__ import annotations

import json
import math
from typing import Any, Dict

from metaphysica.generators._common import autogen_dir
from metaphysica.simulations.core.canonical_values import all_canonical

# canonical symbol -> registry path expected to agree (rel tol 1e-3)
REGISTRY_BINDINGS = {
    "w0": "cosmology.w0_derived",
    "wa": "cosmology.wa_derived",
    "H0_km_s_Mpc": "cosmology.H0_local",
    "theta13_deg": "neutrino.theta_13_pred",
    "sin2_theta_w": "gauge.sin2_theta_w",
    "tau_p_years": "proton_decay.lifetime_years",
    "alpha_leak": None,   # multiple consumers; naming ruling only
}


def main() -> int:
    canon = all_canonical()

    params_path = autogen_dir() / "parameters.json"
    registry: Dict[str, Any] = {}
    if params_path.exists():
        registry = json.loads(params_path.read_text(encoding="utf-8")).get("parameters", {})

    drift = []
    for symbol, entry in canon.items():
        path = REGISTRY_BINDINGS.get(symbol)
        cv = entry.get("value")
        if not path or cv is None or path not in registry:
            continue
        rv = registry[path].get("value")
        if isinstance(rv, (int, float)) and isinstance(cv, (int, float)):
            rel = abs(rv - cv) / max(abs(cv), 1e-30)
            if rel > 1e-3:
                drift.append({"symbol": symbol, "registry_path": path,
                              "canonical": cv, "registry": rv, "rel": rel})

    payload = {
        "schema_version": 1,
        "note": (
            "Canonical-value rulings (2026-08 peer review, C-1). Chosen "
            "under the minimal-spare-variables principle: the candidate "
            "derived from b3=24 + structural integers with fewest extra "
            "inputs wins unless data falsified it — falsified elegant "
            "candidates stay on the books labelled FALSIFIED. Prose and "
            "displays must read this table, never restate values."
        ),
        "rulings": canon,
        "registry_drift": drift,
    }
    out = autogen_dir() / "canonical_values.json"
    out.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")

    print("=" * 60)
    print("Canonical-value rulings")
    print("=" * 60)
    print(f"  rulings: {len(canon)}   registry bindings checked: "
          f"{sum(1 for s in canon if REGISTRY_BINDINGS.get(s) in registry)}   "
          f"drift: {len(drift)}")
    for d in drift:
        print(f"  [DRIFT] {d['symbol']:16s} canonical={d['canonical']:.6g} "
              f"registry({d['registry_path']})={d['registry']:.6g}")
    print(f"\nReport written to: {out}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
